import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for a newcomer → 115 G (100 base + 10 first insurance + 5 fee)");
    it.todo("plain amulet, staff and potion use their price-list base premiums (60/80/40 G)");
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed steel sword, enchantment 3 → 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("customer with exactly 2 years with MHPCO → loyalty discount applies");
    it.todo("cursed sword + plain amulet → cursed surcharge applies only to the sword's base (210 G before policy modifiers and fee)");
    it.todo("fractional premium is rounded up in the MHPCO's favor");
    it.todo("follow-up contract gets 15 % discount; first insurance still applies (3-year customer, second quote, cursed sword ench 7 → 160 G)");
  });

  describe("claim — payouts", () => {
    it.todo("regular steel sword enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("fractional payout is rounded down (350.5 G → 350 G)");
    it.todo("dragon attack on sword (500 G) and amulet (300 G) → payout 600 G (deductible per damaged item)");
    it.todo("two swords insured, both damaged → each damage has its own deductible, cap 4000 G");
  });

  describe("claim — cap", () => {
    it.todo("sword + amulet → cap 3200 G (remainingCap reflects insurance sum 1600 G)");
    it.todo("cursed sword → cap 2000 G based on unmodified insurance value");
    it.todo("sword + 3 runes (block) → insurance sum 1750 G, cap 3500 G");
    it.todo("two successive 1500 G claims on a sword → 1400 G (remaining 600 G), then 600 G (remaining 0 G)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) is rejected");
    it.todo("claim for an item not part of the policy is rejected");
    it.todo("claim with more damages of a type than insured is rejected");
    it.todo("claim with negative damage amount is rejected");
  });

  describe("CLI", () => {
    it.todo("reads the scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero with an error on stderr and no results on stdout for an invalid scenario");
  });
});

