const quotePremium = (items: Item[], yearsWithMHPCO: number): number => {
  const policyBase = policyBasePremium(items);
  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
  const riskSurcharges = sum(items.map(itemRiskSurcharge));
  const loyalty = isLongStanding(yearsWithMHPCO) ? policyBase * LOYALTY_DISCOUNT : 0;
  return roundPremiumUp(policyBase + riskSurcharges - loyalty + firstInsurance + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  return { results: [{ premium: quotePremium(scenario.steps[0].items, scenario.customer.yearsWithMHPCO) }] };
};

